# import
import numpy as np

# ----------------------------------------------------------------------------------------------------------------------
# Useful functions for I/O file handling
# ----------------------------------------------------------------------------------------------------------------------
def readInputFile(instanceName):
    with open(instanceName + '.txt', 'r') as ifile:
        # 'J' meter groups
        ifile.readline()
        J = int(((ifile.readline()).split())[0])

        # 'K' substitution squads
        ifile.readlines(2)
        K = int(((ifile.readline()).split())[0])

        # 'T' time intervals per year
        ifile.readlines(2)
        T = int(((ifile.readline()).split())[0])

        # 'Nj' traditional meters to be substituted in meter group j
        ifile.readlines(2)
        N = []
        for _ in range(J):
            N.append(int(((ifile.readline()).split())[0]))

        # Convert 'N' into a 1D NumPy array
        N = np.array(N)

        # 'Q' installation capacity (for each substitution squad)
        ifile.readlines(2)
        Q = int(((ifile.readline()).split())[0])

        # 'bjt' takes value 1 if substitutions can occur in meter group j (row) during time interval t (column), 0 otherwise
        ifile.readlines(2)
        b = []
        for _ in range(J):
            line_b = list(map(int, (ifile.readline()).split()))
            b.append(line_b)

        # Convert 'b' into a 2D NumPy array
        b = np.array(b)

        # 'sigma' meter groups that can be served in a time interval (by the same substitution squad)
        ifile.readlines(2)
        sigma = int(((ifile.readline()).split())[0])

        # 'Sjt' conditional cost savings obtained for meter group j (row) during each time interval t if readings are collected by smart meters instead of traditional meters
        ifile.readlines(2)
        S1 = []
        for _ in range(J):
            line_S1 = list(map(float, (ifile.readline()).split()))
            S1.append(line_S1)

        # Convert 'S1' into a 2D NumPy array
        S1 = np.array(S1)

        # 'Sj' annual conditional cost savings
        ifile.readlines(2)
        S2 = []
        for _ in range(J):
            S2.append(float(((ifile.readline()).split())[0]))

        # Convert 'S2' into a 1D NumPy array
        S2 = np.array(S2)

        # 'SP' operational horizon (i.e., number of years)
        ifile.readlines(2)
        SP = int(((ifile.readline()).split())[0])

        # 'DH' depreciation horizon (i.e., number of years)
        ifile.readlines(2)
        DH = int(((ifile.readline()).split())[0])

        # 'r' annual cost of capital
        ifile.readlines(2)
        r = float(((ifile.readline()).split())[0])

        # 'gamma' annual tax rate
        ifile.readlines(2)
        gamma = float(((ifile.readline()).split())[0])

        # 'C' investment cost for the purchase and installation of a smart meter
        ifile.readlines(2)
        C = float(((ifile.readline()).split())[0])

        # 'name' of the instance
        ifile.readlines(2)
        instanceName = ((ifile.readline()).split())[0]

    return J, K, T, N, Q, b, sigma, S1, S2, SP, DH, r, gamma, C, instanceName

def writeOutputModelFile(*args):
    # args[0] = instanceName
    # args[1] = model
    with open('output/results_bc_' + args[0] + '.txt', 'w') as ofile:
        ofile.write('Instance: {}'.format(args[0]))
        ofile.write('\nNumConstrs: {}'.format(args[1].NumConstrs))
        ofile.write('\nNumVars: {}'.format(args[1].NumVars))
        ofile.write('\nNumNZs: {}'.format(args[1].NumNZs))
        ofile.write('\nNumIntVars (i.e., includes both binary variables and general integer variables): {}'.format(args[1].NumIntVars))
        ofile.write('\nNumBinVars: {}'.format(args[1].NumBinVars))
        ofile.write('\nModelName: {}'.format(args[1].ModelName))
        ofile.write('\nModelSense: {} (1 -- \'minimization\', -1 -- \'maximization\')'.format(args[1].ModelSense))
        ofile.write('\nObjVal: {:.2f}'.format(args[1].ObjVal))
        ofile.write('\nObjBound: {:.2f}'.format(args[1].ObjBound))
        ofile.write('\nMIPGap: {:.4f}'.format(args[1].MIPGap))
        ofile.write('\nRuntime: {:.2f}'.format(args[1].Runtime))
        ofile.write('\nStatus: {} (2 -- \'OPTIMAL\')'.format(args[1].Status))

